svg.script:
function show_7b9df7bd(evt, text) {
	var pos = (evt.target.getAttribute("y") < 714) ? "bottom" : "top";
	var note = document.getElementById(pos + "_note_7b9df7bd");
	note.textContent = text;
	note.setAttributeNS(null, "visibility", "visible");
	document.getElementById(pos + "_overlay_7b9df7bd").setAttributeNS(null, "visibility", "visible");
}
function hide_7b9df7bd(evt) {
	document.getElementById("top_note_7b9df7bd").setAttributeNS(null, "visibility", "hidden");
	document.getElementById("top_overlay_7b9df7bd").setAttributeNS(null, "visibility", "hidden");
	document.getElementById("bottom_note_7b9df7bd").setAttributeNS(null, "visibility", "hidden");
	document.getElementById("bottom_overlay_7b9df7bd").setAttributeNS(null, "visibility", "hidden");
}
